import { Tag } from '@aws-sdk/client-ec2';
import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { Logger } from '@nestjs/common';
import { randomUUID } from 'crypto';
import EventEmitter from 'events';
import { AuditService } from '../../audit/audit.service';
import { AuditScope } from '../../audit/entities/audit.interface';
import { InfluxService } from '../../influx/influx.service';
import { MeasurementFormat } from './measurement.interface';

const eventEmitter = new EventEmitter();
export enum DlqType {
    s3 = 's3',
}
export class StandardMeasurementEntity implements MeasurementFormat {
    private static readonly logger = new Logger(StandardMeasurementEntity.name);
    public timeStamp?: string;
    public dimensionId?: string;
    public businessID: string;
    public applicationId?: string;
    public serviceId?: string;
    public recordValue: number;
    public metadata: Record<string, string>;
    public _measurement: string;
    public static allowedTags = ['paigoApplicationId', 'paigoServiceId', 'paigoDimensionId'];

    constructor(measurement: MeasurementFormat) {
        if (measurement.timeStamp) {
            this.timeStamp = measurement.timeStamp;
        } else {
            this.timeStamp = new Date().toISOString();
        }
        this.dimensionId = measurement.dimensionId;
        this.applicationId = measurement.applicationId;
        this.serviceId = measurement.serviceId;
        this.recordValue = measurement.recordValue;
        this.metadata = measurement.metadata;
        this.businessID = measurement.businessID;
        this._measurement = measurement._measurement;
    }
    static publish(publishRequest: MeasurementFormat) {
        eventEmitter.emit('standardMeasurements', publishRequest);
        return {
            message: 'published',
            id: randomUUID(),
            data: [publishRequest],
        };
    }
    static subscribe(influxService: InfluxService) {
        eventEmitter.on('standardMeasurements', async (measurementFormat: MeasurementFormat) => {
            const point = MeasurementFormat.getPointForm(measurementFormat, influxService);
            try {
                await influxService.loadPoints(`${process.env.STAGE}-usage-data`, `paigo`, [point]);
            } catch (err) {
                AuditService.publishEvent({
                    data: [{ err }],
                    message: 'Failed to index Measurement',
                    topic: AuditScope.ERROR,
                });
            }
        });
    }
    static awsTagKeyReducer(Tags: Tag[]) {
        if (Tags) {
            return Tags.reduce((acc, { Key, Value }): any => {
                if (StandardMeasurementEntity.allowedTags.includes(Key)) {
                    acc[Key] = Value;
                }
                return acc;
            }, {});
        } else {
            return {};
        }
    }

    static async publishFailureToDLQ(failedDocument, metadata: MeasurementFailureMetadata, dlqType: DlqType) {
        if (dlqType === DlqType.s3) {
            const s3 = new S3Client({ region: 'us-east-1' });
            const params = {
                Bucket: process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME,
                Key: `${metadata.orginalProcessedName}-${(Math.random() + 1).toString(36).substring(7)}.json`,
                Body: JSON.stringify({ failedDocument: failedDocument, metadata }),
            };
            try {
                await s3.send(new PutObjectCommand(params));
            } catch (e) {
                StandardMeasurementEntity.logger.error('error occurred writing to dlq', e);
                AuditService.publishEvent({
                    topic: AuditScope.ERROR,
                    message: 'Failed to write to DLQ',
                    data: [
                        {
                            errorCode: e?.Code,
                            errorMessage: e?.message,
                            errorName: e?.name,
                            failedDocument,
                            metadata,
                            dlqType,
                        },
                    ],
                });
            }
        }
    }
}

export class MeasurementFailureMetadata {
    timestamp: string;
    results: string;
    errorInfo: any;

    /**
     * This is the processed name from the system where the measurement occured
     * In S3 its the complete fileName
     * */
    orginalProcessedName: string;

    constructor({ timestamp, results }: MeasurementFailureMetadata) {
        this.timestamp = timestamp;
        this.results = results;
    }
}
import { ApiHideProperty } from '@nestjs/swagger';
import { IsString, IsOptional, IsNotEmpty, IsObject, IsRFC3339, IsNumberString, IsAscii } from 'class-validator';

import { ValidServiceApplicationID } from './measurementIdOrApplicationIdValidator';
import { ServiceIdExists } from '../../services/dto/serviceIdExists';
import { DimensionIdExists } from '../../dimensions/dto/dimensionIdExists';

export class CreateStandardMeasurementDto {
    /**
     * The businessID associated with your account, not needed for full accounts, this is gathered during authentication
     * @example 'My Cool Corp'
     *
     **/
    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public businessID: string;

    /**
     * The timestamp of usage record in <a href="https://ijmacd.github.io/rfc3339-iso8601/">RFC3339</a>
     * format with a 4-digit year.
     * This is the time the usage occurred, or the end of the usage period.
     * <br><br>
     * Example: `"2023-02-08T19:24:10Z"`
     *
     **/
    @IsRFC3339()
    @IsString()
    @IsNotEmpty()
    public timeStamp: string;

    /**
     * Conditionally REQUIRED.<br>
     * The application ID of a service this usage record attributes to.
     * This field is required if the `serviceId` is not provided.
     * If both are provided the `serviceId` takes precedence
     * and both  persist in usage records.
     * <br><br>
     * Example: `"e8366954-6f36-47e9-8431-ac95f88b5cc7"`
     *
     **/
    @IsString()
    @IsOptional()
    @IsAscii()
    public applicationId?: string;

    /**
     * Conditionally REQUIRED.<br>
     * The service ID of a service this usage record attributes to.
     * This field is required if the `applicationId` is not provided.
     * If both are provided the `serviceId` takes precedence
     * and both persist in usage records.
     * <br><br>
     * Example: `'e8366954-6f36-47e9-8431-ac95f88b5cc7'`
     *
     **/
    @ValidServiceApplicationID('serviceId', {
        message: 'Must provide either a serviceId or a applicationId',
    })
    @ServiceIdExists('serviceId')
    public serviceId?: string;

    /**
     * The unique identifier of the dimension this usage record is associated with.
     * <br><br>
     * Example: `'da9611bd-e0f3-4c0d-a754-fda5be730872'`
     *
     **/
    @IsString()
    @IsNotEmpty()
    @DimensionIdExists('dimensionId')
    public dimensionId?: string;

    /**
     * The amount of the usage on this record.
     * Numerical values are represented as strings to avoid precision loss.
     * <br><br>
     * Example: `"0.87"`
     **/
    @IsNumberString()
    @IsString()
    public recordValue: string;

    /**
     * An optional key-value map of additional metadata to associate with this usage record.
     * Additional metadata to be stored on the usage record,
     * such as environment, purpose, owner, developer, contract number,
     * or any arbitrary data to be associated with this usage record.
     * Metadata can be used for analytics purpose.
     * <br><br>
     * Example `{"environment": "staging", "purpose": "proof-of-concept", "owner": "John Doe"}`
     **/
    @IsObject()
    @IsOptional()
    public metadata: Record<string, string>;

    constructor(doc) {
        if (doc) {
            this.businessID = doc.businessID;
            this.timeStamp = doc.timeStamp;
            this.applicationId = doc.applicationId;
            this.serviceId = doc.serviceId;
            this.dimensionId = doc.dimensionId;
            this.recordValue = doc.recordValue;
            this.metadata = doc.metadata;
        }
    }
}

import { Point } from '@influxdata/influxdb-client';
import { MeasurementInfluxDbModel } from '../../influx/entities/measurementInfluxDbModel.interface';
import { InfluxService } from '../../influx/influx.service';
export enum ValidMeasurementTypes {
    int = 'int',
    float = 'float',
}

export abstract class MeasurementFormat {
    dimensionId?: string;
    applicationId?: string;
    serviceId?: string;
    timeStamp?: string;
    recordValue: number;
    businessID: string;
    metadata: Record<string, string>;
    _measurement: string;
    static getPointForm(measurement: MeasurementFormat, influxService: InfluxService): Point {
        const point = influxService.getPoint(measurement._measurement);
        point.timestamp(new Date(measurement.timeStamp));
        point.tag('applicationId', measurement.applicationId);
        point.tag('dimensionId', measurement.dimensionId);
        point.tag('serviceId', measurement.serviceId);
        point.tag('businessID', measurement.businessID);
        point.floatField('recordValue', measurement.recordValue);
        if (measurement?.metadata) {
            Object.keys(measurement.metadata).forEach((key) => {
                point.tag(`metadata_${key}`, measurement.metadata[key]);
            });
        }
        return point;
    }
    static toEntity(dbModel: MeasurementInfluxDbModel): MeasurementFormat {
        const measurementInput: MeasurementFormat = {
            timeStamp: dbModel._time,
            dimensionId: dbModel.dimensionId,
            applicationId: dbModel.applicationId,
            recordValue: dbModel._value,
            metadata: {},
            _measurement: dbModel._measurement,
            businessID: dbModel.businessID,
        };
        Object.keys(dbModel).forEach((key) => {
            if (key.startsWith('metadata_') && dbModel[key]) {
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore
                measurementInput.metadata[key.replace('metadata_', '')] = dbModel[key];
            }
        });
        return measurementInput;
    }
}
