                    const timeRange = `${isoStartTime}##${isoEndTime}`;
                    if (!timeRanges.includes(timeRange)) {
                        return { timeRange, value: 0 };
                    }
                    return { timeRange, value: uniqueIdsUpTimeHours[item][timeRange] };
