const vmList = [];

for await (const item of computeClient.virtualMachines.listByLocation(region)) {
    vmList.push(item);
}

const taggedVms = vmList.filter((vm) => {
    const tags = vm.tags || {};
    if (!tags.paigoDimensionId || tags.paigoDimensionId.trim() === '') {
        return false;
    } else if (
        (!tags.paigoApplicationId || tags.paigoApplicationId.trim() === '') &&
        (!tags.paigoServiceId || tags.paigoServiceId.trim() === '')
    ) {
        return false;
    }
    return tags.paigoDimensionId === dimensionId;
});

const qualifiedVms = [];
for (const vm of taggedVms) {
